root=EvaluateActionModel(evaluate=evaluate_Params(code="(function(){
  function findInShadow(root, selector) {
    let el = root.querySelector(selector);
    if (el) return el;
    for (const child of root.querySelectorAll('*')) {
      if (child.shadowRoot) {
        const res = findInShadow(child.shadowRoot, selector);
        if (res) return res;
      }
    }
    return null;
  }
  const input = findInShadow(document, '#startingAt');
  if (input) {
    input.focus();
    const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    nativeSetter.call(input, 'New York');
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
    return 'Value set to ' + input.value;
  }
  return 'Element #startingAt not found';
})()"))

